test("a failed later window resumes from reviewed checkpoints instead of requesting earlier windows again", async () => {
 browser();
 const data = new Map<string,string>();
 const cache = {key:'same-source',storage:{getItem:(k:string)=>data.get(k)??null,setItem:(k:string,v:string)=>{data.set(k,v)},removeItem:(k:string)=>{data.delete(k)}}};
 const requested: number[]=[];let fail=true;
 globalThis.fetch=mock(async(url,init)=>{
  if(String(url).includes('connection'))return Response.json({models:[{id:'test'}]});
  const prompt=JSON.parse(JSON.parse(String(init?.body)).input[0].content);
  if(prompt.index!==undefined){requested.push(prompt.index);if(prompt.index===2&&fail)return Response.json({error:'Our servers are currently overloaded. Please try again later.'},{status:503});return stream([{...video,title:`window-${prompt.index}`}]);}
  return stream([video]);
 }) as unknown as typeof fetch;
 const input={source:{...source,windows:[0,1,2].map(index=>({index,words}))},options:{mode:'highlights' as const,minSeconds:20,maxSeconds:60,maxOutputs:4},signal:new AbortController().signal,onStage:()=>{},review:()=>{},cache};
 await expect(requestPodcastPlan(input)).rejects.toThrow('overloaded');
 expect(data.size).toBe(2);
 fail=false;
 expect(await requestPodcastPlan(input)).toEqual([video]);
 expect(requested).toEqual([0,1,2,2]);
});

